  Object.assign(state,{a79Scene:'',a79Mode:'ready',a79Pie:false,a79Selected:-1,a79HeaderHint:true,a79ChartHint:true});
  const a79Scenes=[['analytics-income','洞察 · 收入','income','ready'],['analytics-balance','洞察 · 结余','balance','ready'],['analytics-year','洞察 · 年度','expense','ready'],['analytics-all','洞察 · 全部年份','expense','ready'],['analytics-empty','洞察 · 空周期','expense','empty'],['analytics-loading','洞察 · 加载中','expense','loading'],['analytics-error','洞察 · 读取失败','expense','error'],['analytics-pie','洞察 · 分类环图','expense','ready'],['analytics-foreign','洞察 · 补折算确认','expense','ready']];
  function a79Prepare(key){if(state.a79Scene===key)return;state.a79Scene=key;const s=a79Scenes.find(s=>s[0]===key);state.report=s?.[2]||'expense';state.period=key.endsWith('year')?'year':key.endsWith('all')?'all':'month';state.a79Mode=s?.[3]||'ready';state.a79Pie=key.endsWith('pie');state.a79Selected=-1;state.a79HeaderHint=true;state.a79ChartHint=true;}
  function a79Value(n){return state.hide?'****':money(n).replace(/(\.\d*?)0+$/,'$1').replace(/\.$/,'');}
  function a79Data(){if(state.a79Mode==='empty')return {expense:0,income:0,count:0};const v=totals(),factor=state.period==='month'?1:state.period==='year'?9.2:21;return {expense:v.expense*factor,income:v.income*factor,count:state.report==='balance'?27:state.report==='income'?1:26};}
  function a79Trend(){const balance=state.report==='balance',values=balance?[25,35,22,60,45,15,48,44,30,65,20,36,49,73,45,38,32,54,69,90]:[28,38,24,62,48,19,55,42,32,67,22,39,52,77,48,41,35,58,72,92],points=values.map((v,i)=>`${16+i*14},${196-v*1.6}`).join(' ');return `<div class="a79-trend" role="img" aria-label="收支折线趋势"><svg viewBox="0 0 308 240" preserveAspectRatio="none"><line x1="16" y1="120" x2="292" y2="120" stroke="var(--bc-muted)" stroke-dasharray="4 4"/><polyline points="${points}" fill="none" stroke="var(--bc-accent)" stroke-width="2"/>${values.map((v,i)=>`<circle cx="${16+i*14}" cy="${196-v*1.6}" r="2.5" fill="var(--bc-accent)"/>`).join('')}<text x="16" y="232">1</text><text x="145" y="232">10</text><text x="278" y="232">20</text></svg><div class="a79-chart-actions">${btn('a79-prev','‹','上个周期')}${btn('a79-point','20','选择趋势点')}${btn('a79-next','›','下个周期')}</div></div>${state.a79Selected>=0?`<p class="bc-small" role="status">20 · ${state.hide?'****':'¥145.00'}</p>`:''}${state.a79ChartHint?`<div class="a79-hint"><span>⇆ 左右滑动切换周期</span>${btn('a79-close-chart',icon('x'),'关闭周期提示')}</div>`:''}`;}
  function a79Rank(){const total=state.report==='income'?a79Data().income:a79Data().expense;return surface(`<div class="bc-between"><h3>分类排行</h3>${btn('a79-toggle',icon(state.a79Pie?'list':'chart-pie'),state.a79Pie?'显示分类排行':'显示分类环图','bc-icon')}</div>${state.a79HeaderHint?`<div class="a79-hint"><span>⇆ 横滑切换</span>${btn('a79-close-header',icon('x'),'关闭视角提示')}</div>`:''}${state.a79Pie?`<div class="a79-pie"><div class="bc-donut"><span>${state.a79Selected<0?'总计':'餐饮'}<b>${a79Value(Math.round(total*(state.a79Selected<0?1:.365)))}</b></span></div>${[['餐饮',36.5],['购物',28],['居家',19.5],['交通',16]].map(([n,p],i)=>btn(`a79-slice:${i}`,`${n} ${a79Value(Math.round(total*p/100))} (${p}%)`,n,'bc-tag')).join('')}</div>`:dRanking().replace(/class="bc-num">([\d,.]+)/g,(_,n)=>'class="bc-num">'+Math.round(Number(n.replace(/,/g,''))).toLocaleString('en-US')).replace(/\d+笔 · 占/g,'').replace(/<small>\d+笔<\/small>/g,'').replace(/^<section[^>]*>/,'<div>').replace(/<\/section>$/,'</div>').replace(/<div class="bc-between"><h3>分类排行<\/h3>.*?<\/div>/,'')}`);}
  function a79Summary(d,total,label,period,avg){return surface(`<div class="bc-between a79-summary-selectors">${btn('a79-period',`${period}${state.period==='all'?'':icon('chevron-down')}`,'选择统计周期','',state.period==='all'?'disabled':'')}${btn('a79-view',`${label}${icon('chevron-down')}`,'选择统计视角')}</div><span class="bc-small">总${label}：</span><div class="a79-total bc-num">${state.hide?'****':'¥'+a79Value(total)}</div><div class="bc-dual"><div><label>记账笔数</label><strong>${d.count}</strong></div><div><label>${avg}</label><strong>${state.hide?'****':'¥'+a79Value(total/(state.period==='month'?20:state.period==='year'?10:3))}</strong></div></div>`,'a79-summary');}
  function a79Page(){const d=a79Data(),total=state.report==='balance'?d.income-d.expense:d[state.report],label={expense:'支出',income:'收入',balance:'结余'}[state.report],period=state.period==='all'?'全部年份':state.period==='year'?String(state.year):`${state.year}-${String(state.month).padStart(2,'0')}`,avg=state.period==='month'?'日均':state.period==='year'?'月均':'平均值';return `<div class="a79-shell">${tophead('洞察',btn('page:ai',icon('sparkles'),'蜜蜂 AI','bc-icon')+btn('a79-share',icon('share-2'),'分享','bc-icon'))}<div class="bc-segment bc-period">${[['month','月'],['year','年'],['all','全部']].map(([k,n])=>btn(`a79-scope:${k}`,n,n+'统计','',`aria-pressed="${state.period===k}"`)).join('')}</div><div class="a79-scroll">${state.a79Scene.endsWith('foreign')?surface(`<div class="bc-between"><span>有外币账单尚未折算</span>${btn('a79-recalc','补折算','补折算')}</div>`):''}<p class="bc-small">统计金额已折算为 CNY</p>${['ready','empty'].includes(state.a79Mode)?a79Summary(d,total,label,period,avg):''}${state.a79Mode==='loading'?'<div class="a79-loading" role="status">正在读取统计…</div>':state.a79Mode==='error'?surface(`<h3>读取失败</h3>${btn('a79-retry','重试','重试','bc-primary')}`):state.a79Mode==='empty'?surface(`<div class="cl-empty">暂无数据</div><p>可左右滑动切换周期，或点击按钮切换收入/支出</p>${btn('a79-switch','切换到收入','切换统计视角','bc-secondary')}`):surface(`<h3>收支趋势</h3>${a79Trend()}`,'a79-trend-card')+(state.report==='balance'?'':a79Rank())}${menuCard([['leaf:年度账单','chart-no-axes-combined','年度账单','回顾一整年的小日常'],['a79-share','image','生成分享海报','年度、月度与总览']])}</div></div>`;}
  report=function(){a79Prepare('report');return a79Page();};
  for(const[k,title]of a79Scenes)fDefine(k,title,'主要页面','main/analytics_page.dart',a79Page);
  const a79Render=fRender;fRender=function(key){if(a79Scenes.some(s=>s[0]===key)){a79Prepare(key);return a79Page();}return a79Render(key);};
  rSpecs['a79-view']={title:'统计视角',host:'report',kind:'dialog'};
  rSpecs['a79-recalc']={title:'补折算',host:'report',kind:'dialog'};
  rSpecs['a79-period']={title:'选择周期',host:'report',kind:'sheet'};
  const a79Modal=rModalBody;rModalBody=function(key){if(key==='a79-view')return `<div class="a79-options">${[['expense','支出'],['income','收入'],['balance','结余']].map(([k,n])=>btn(`a79-type:${k}`,`${state.report===k?'◉':'○'} ${n}`,n)).join('')}</div>`;if(key==='a79-recalc')return `<p>按当前有效汇率补齐外币折算，原币金额保持。</p><div class="j-picker-actions">${btn('r-close','取消','取消','bc-secondary')}${btn('a79-confirm-recalc','确定','确定','bc-primary')}</div>`;if(key==='a79-period'){const d=jDraft('month');return jWheelGroup(jWheel('year',Array.from({length:27},(_,i)=>2000+i),d.year,'年','年份')+(state.period==='year'?'':jWheel('month',Array.from({length:d.year===2026?10:12},(_,i)=>i+1),d.month,'月','月份')))+`<div class="j-picker-actions">${btn('r-close','取消','取消','bc-secondary')}${btn('a79-confirm-period','确定','确定','bc-primary')}</div>`;}return a79Modal(key);};
  function a79Move(delta){if(state.period==='all')return;if(state.period==='year'){state.year=Math.min(2026,state.year+delta);}else{const d=new Date(state.year,state.month-1+delta,1);if(d<=new Date(2026,9,1)){state.year=d.getFullYear();state.month=d.getMonth()+1;}}state.a79Selected=-1;}
  root.addEventListener('click',e=>{const el=e.target.closest('[data-action]'),a=el?.dataset.action;if(!a?.startsWith('a79-'))return;e.preventDefault();e.stopImmediatePropagation();const[k,v]=a.split(':');if(k==='a79-scope')state.period=v;else if(k==='a79-type'){state.report=v;rDismiss();}else if(k==='a79-toggle')state.a79Pie=!state.a79Pie;else if(k==='a79-switch')state.report=state.report==='expense'?'income':state.report==='income'?'balance':'expense';else if(k==='a79-view'||k==='a79-recalc'){rOpenModal(k);return;}else if(k==='a79-period'){state.jWheel={kind:'month',year:state.year,month:state.month};rOpenModal(k);return;}else if(k==='a79-confirm-period'){for(const w of phone.querySelectorAll('[data-j-wheel]'))jWheelRead(w);state.year=state.jWheel.year;state.month=state.jWheel.month;rDismiss();}else if(k==='a79-confirm-recalc'){rDismiss();notice('设计预览：补折算完成');}else if(k==='a79-share'){state.fForm.shareScope=state.period;navigate('poster');return;}else if(k==='a79-slice')state.a79Selected=Number(v);else if(k==='a79-point')state.a79Selected=20;else if(k==='a79-prev'||k==='a79-next')a79Move(k==='a79-prev'?-1:1);else if(k==='a79-retry')state.a79Mode='ready';else if(k==='a79-close-chart')state.a79ChartHint=false;else if(k==='a79-close-header')state.a79HeaderHint=false;render();},true);
